#include "stdlib/math/base/special/log1pexpf.h"
#include "stdlib/constants/float32/nan.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/special/log1pf.h"
#include "stdlib/math/base/special/expf.h"

/**
* Computes the natural logarithm of \\( 1 + \exp(x) \\) for a single-precision floating-point number.
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_log1pexpf( 0.0f );
* // returns ~0.693f
*/
float stdlib_base_log1pexpf( const float x ) {
	if ( stdlib_base_is_nanf( x ) ) {
		return STDLIB_CONSTANT_FLOAT32_NAN;
	}
	if ( x <= -17.0f ) {
		return stdlib_base_expf( x );
	}
	if ( x <= 9.0f ) {
		return stdlib_base_log1pf( stdlib_base_expf( x ) );
	}
	if ( x <= 16.0f ) {
		return x + stdlib_base_expf( -x );
	}
	// Case: x > 16.0f
	return x;
}
